// Test multiple scenarios
const tests = [
  { name: 'Simple mapping', yaml: 'key: value' },
  { name: 'List', yaml: '- item1\\n- item2' },
  { name: 'Nested', yaml: 'parent:\\n  child: value' },
  { name: 'Multi-doc', yaml: '---\\nkey1: val1\\n---\\nkey2: val2' },
  { name: 'Comments', yaml: '# comment\\nkey: value' },
];

for (const test of tests) {
  try {
    const result = Bun.YAML.parse(test.yaml);
    console.log(\`✓ \${test.name}: \${JSON.stringify(result)}\`);
  } catch (e) {
    console.log(\`✗ \${test.name}: \${e.message}\`);
  }
}
"

