// Proof-of-concept YAML validator using Bun.YAML
// This tests whether Bun's built-in YAML support is sufficient for a validator command

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  warnings: ValidationWarning[];
}

interface ValidationError {
  line: number;
  column: number;
  message: string;
  context: string;
}

interface ValidationWarning {
  line: number;
  message: string;
}

export function validateYAML(content: string): ValidationResult {
  const errors: ValidationError[] = [];
  const warnings: ValidationWarning[] = [];

  try {
    const parsed = Bun.YAML.parse(content);

    // Basic validation checks
    if (parsed === null || parsed === undefined) {
      warnings.push({
        line: 1,
        message: "YAML content is empty or null"
      });
    }

    // Check for common issues
    const lines = content.split('\n');
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];

      // Warn about tab usage
      if (line.includes('\t')) {
        warnings.push({
          line: i + 1,
          message: "Line contains tabs; YAML recommends spaces"
        });
      }
    }

    return {
      valid: true,
      errors,
      warnings
    };
  } catch (e) {
    if (e instanceof SyntaxError) {
      const line = (e as any).line ?? (e as any).originalLine ?? 1;
      const column = (e as any).column ?? (e as any).originalColumn ?? 0;

      errors.push({
        line,
        column,
        message: e.message,
        context: content.split('\n')[line - 1] || ''
      });
    }

    return {
      valid: false,
      errors,
      warnings
    };
  }
}

// Test cases demonstrating validator capability
const testCases = [
  { name: "Valid simple", yaml: "key: value" },
  { name: "Valid nested", yaml: "parent:\n  child: value" },
  { name: "Valid list", yaml: "- item1\n- item2\n- item3" },
  { name: "Valid multi-doc", yaml: "---\nkey1: val1\n---\nkey2: val2" },
  { name: "Invalid syntax", yaml: "key: [unclosed" },
  { name: "Invalid indentation", yaml: "key:\n value: bad" }
];

console.log("YAML Validator Test Results:\n");
for (const test of testCases) {
  const result = validateYAML(test.yaml);
  console.log(`Test: ${test.name}`);
  console.log(`  Valid: ${result.valid}`);
  if (result.errors.length > 0) {
    console.log(`  Errors: ${result.errors.map(e => `Line ${e.line}: ${e.message}`).join('; ')}`);
  }
  if (result.warnings.length > 0) {
    console.log(`  Warnings: ${result.warnings.map(w => `Line ${w.line}: ${w.message}`).join('; ')}`);
  }
  console.log();
}
EOF
