/**
 * Lightweight YAML syntax validator using pure TypeScript.
 * No external dependencies - uses only built-in Bun/Node.js APIs.
 */

export type TokenType =
  | "key"
  | "value"
  | "scalar"
  | "comment"
  | "indent"
  | "dash"
  | "bracket"
  | "brace"
  | "colon"
  | "comma"
  | "quote"
  | "newline";

export interface Token {
  type: TokenType;
  value: string;
  line: number;
  column: number;
}

export interface ValidationError {
  file: string;
  line: number;
  column: number;
  message: string;
  context?: string;
}

export interface ValidationResult {
  valid: boolean;
  file: string;
  errors: ValidationError[];
}

/**
 * Validates YAML content from a string.
 * Returns a ValidationResult with error details if invalid.
 */
export function validateYAML(
  content: string,
  filename: string
): ValidationResult {
  const errors: ValidationError[] = [];
  const lines = content.split("\n");

  try {
    const tokens = tokenize(content);
    const parseResult = parseTokens(tokens, lines);

    if (!parseResult.valid) {
      errors.push(...parseResult.errors);
    }
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Unknown parsing error";
    errors.push({
      file: filename,
      line: 1,
      column: 0,
      message: `Parse error: ${message}`,
    });
  }

  return {
    valid: errors.length === 0,
    file: filename,
    errors,
  };
}

/**
 * Validates multiple YAML files.
 * Uses only fs module which is available in Bun runtime.
 */
export function validateYAMLFiles(filePaths: string[]): ValidationResult[] {
  const results: ValidationResult[] = [];

  for (const filePath of filePaths) {
    try {
      // Use Bun/Node.js built-in fs module
      const fs = require("fs");
      const content = fs.readFileSync(filePath, "utf-8");
      results.push(validateYAML(content, filePath));
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown file error";
      results.push({
        valid: false,
        file: filePath,
        errors: [
          {
            file: filePath,
            line: 0,
            column: 0,
            message: `File error: ${message}`,
          },
        ],
      });
    }
  }

  return results;
}

/**
 * Tokenizes YAML content into a stream of tokens.
 * Extracts tokens with type, value, and position information.
 */
function tokenize(content: string): Token[] {
  const tokens: Token[] = [];
  let line = 1;
  let column = 0;
  let i = 0;

  while (i < content.length) {
    const char = content[i];
    const nextChar = content[i + 1];
    const startColumn = column;

    // Newline
    if (char === "\n") {
      tokens.push({
        type: "newline",
        value: "\n",
        line,
        column: startColumn,
      });
      line++;
      column = 0;
      i++;
      continue;
    }

    // Comments (must be at line start or after space)
    if (char === "#" && (column === 0 || /\s/.test(content[i - 1]))) {
      const start = i;
      while (i < content.length && content[i] !== "\n") {
        i++;
      }
      tokens.push({
        type: "comment",
        value: content.substring(start, i),
        line,
        column: startColumn,
      });
      column += i - start;
      continue;
    }

    // Indentation (spaces at line start)
    if (column === 0 && char === " ") {
      const start = i;
      while (i < content.length && content[i] === " ") {
        i++;
      }
      const indentSize = i - start;
      tokens.push({
        type: "indent",
        value: " ".repeat(indentSize),
        line,
        column: 0,
      });
      column = indentSize;
      continue;
    }

    // Quoted strings (single or double)
    if (char === '"' || char === "'") {
      const quote = char;
      const start = i;
      i++;
      column++;

      while (i < content.length && content[i] !== quote) {
        if (content[i] === "\\" && content[i + 1]) {
          i += 2;
          column += 2;
        } else {
          i++;
          column++;
        }
      }

      if (i >= content.length) {
        // Unclosed quote
        tokens.push({
          type: "quote",
          value: content.substring(start, i),
          line,
          column: startColumn,
        });
        break;
      }

      i++; // closing quote
      column++;
      tokens.push({
        type: "quote",
        value: content.substring(start, i),
        line,
        column: startColumn,
      });
      continue;
    }

    // Structural characters
    if (char === ":") {
      tokens.push({
        type: "colon",
        value: ":",
        line,
        column: startColumn,
      });
      i++;
      column++;
      continue;
    }

    if (char === "-" && (nextChar === undefined || /[\s:]/.test(nextChar))) {
      tokens.push({
        type: "dash",
        value: "-",
        line,
        column: startColumn,
      });
      i++;
      column++;
      continue;
    }

    if (char === "{") {
      tokens.push({
        type: "brace",
        value: "{",
        line,
        column: startColumn,
      });
      i++;
      column++;
      continue;
    }

    if (char === "}") {
      tokens.push({
        type: "brace",
        value: "}",
        line,
        column: startColumn,
      });
      i++;
      column++;
      continue;
    }

    if (char === "[") {
      tokens.push({
        type: "bracket",
        value: "[",
        line,
        column: startColumn,
      });
      i++;
      column++;
      continue;
    }

    if (char === "]") {
      tokens.push({
        type: "bracket",
        value: "]",
        line,
        column: startColumn,
      });
      i++;
      column++;
      continue;
    }

    if (char === ",") {
      tokens.push({
        type: "comma",
        value: ",",
        line,
        column: startColumn,
      });
      i++;
      column++;
      continue;
    }

    // Scalars (everything else)
    const start = i;
    while (
      i < content.length &&
      !/[\n:,\[\]{}"']/.test(content[i]) &&
      !(
        content[i] === "#" &&
        (column === 0 || /\s/.test(content[i - 1]))
      )
    ) {
      i++;
    }

    if (i > start) {
      const value = content.substring(start, i).trimEnd();
      if (value) {
        tokens.push({
          type: "scalar",
          value,
          line,
          column: startColumn,
        });
      }
      column += i - start;
    }

    // Skip remaining whitespace (except newlines)
    while (i < content.length && /[ \t]/.test(content[i])) {
      i++;
      column++;
    }
  }

  return tokens;
}

/**
 * Parses tokens into an abstract structure and validates YAML syntax.
 */
function parseTokens(
  tokens: Token[],
  lines: string[]
): { valid: boolean; errors: ValidationError[] } {
  const errors: ValidationError[] = [];
  let i = 0;

  // Track indentation stack for structure validation
  const indentStack: number[] = [0];
  let expectingValue = false;

  while (i < tokens.length) {
    const token = tokens[i];

    // Process indentation changes
    if (token.type === "indent") {
      const indent = token.value.length;

      if (indent > indentStack[indentStack.length - 1]) {
        indentStack.push(indent);
      } else if (indent < indentStack[indentStack.length - 1]) {
        while (
          indentStack.length > 1 &&
          indentStack[indentStack.length - 1] > indent
        ) {
          indentStack.pop();
        }

        if (indent !== indentStack[indentStack.length - 1]) {
          errors.push({
            file: "unknown",
            line: token.line,
            column: token.column,
            message:
              "Invalid indentation - does not align with previous indentation levels",
            context: lines[token.line - 1],
          });
        }
      }
    }

    // Validate structure patterns
    if (token.type === "colon") {
      // Colon must have a value (scalar/quote) before it
      if (i === 0 || tokens[i - 1].type === "colon") {
        errors.push({
          file: "unknown",
          line: token.line,
          column: token.column,
          message: "Unexpected colon - expected key name before colon",
          context: lines[token.line - 1],
        });
      }

      // After colon, must have value or newline
      if (
        i + 1 < tokens.length &&
        tokens[i + 1].type !== "newline" &&
        tokens[i + 1].type !== "comment" &&
        tokens[i + 1].type !== "scalar" &&
        tokens[i + 1].type !== "quote" &&
        tokens[i + 1].type !== "dash" &&
        tokens[i + 1].type !== "bracket" &&
        tokens[i + 1].type !== "brace"
      ) {
        // Value is optional in YAML (null value allowed)
      }
    }

    // Detect unclosed quotes
    if (token.type === "quote" && token.value[0] === token.value[0]) {
      if (!token.value.endsWith(token.value[0])) {
        errors.push({
          file: "unknown",
          line: token.line,
          column: token.column,
          message: `Unclosed ${token.value[0] === '"' ? "double" : "single"} quote`,
          context: lines[token.line - 1],
        });
      }
    }

    // Check for dash without proper spacing (must be followed by space or bracket)
    if (token.type === "dash") {
      if (
        i + 1 < tokens.length &&
        tokens[i + 1].type !== "newline" &&
        tokens[i + 1].type !== "comment"
      ) {
        const nextToken = tokens[i + 1];
        if (nextToken.column <= token.column + 1) {
          // Not properly spaced
        }
      }
    }

    // Validate bracket/brace matching (simple check)
    if (token.type === "bracket" && token.value === "[") {
      let braceCount = 1;
      let j = i + 1;
      while (j < tokens.length && braceCount > 0) {
        if (tokens[j].type === "bracket") {
          braceCount += tokens[j].value === "[" ? 1 : -1;
        }
        j++;
      }
      if (braceCount !== 0) {
        errors.push({
          file: "unknown",
          line: token.line,
          column: token.column,
          message: "Unclosed bracket",
          context: lines[token.line - 1],
        });
      }
    }

    if (token.type === "brace" && token.value === "{") {
      let braceCount = 1;
      let j = i + 1;
      while (j < tokens.length && braceCount > 0) {
        if (tokens[j].type === "brace") {
          braceCount += tokens[j].value === "{" ? 1 : -1;
        }
        j++;
      }
      if (braceCount !== 0) {
        errors.push({
          file: "unknown",
          line: token.line,
          column: token.column,
          message: "Unclosed brace",
          context: lines[token.line - 1],
        });
      }
    }

    i++;
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Unit tests for yaml-validator module.
 * Tests core YAML validation logic without external dependencies.
 */

import { describe, test, expect } from "bun:test";
import { validateYAML, validateYAMLFiles } from "./yaml-validator";

describe("yaml-validator", () => {
  // Valid YAML tests
  describe("validates valid YAML", () => {
    test("validates simple mapping (key: value)", () => {
      const yaml = "name: John\nage: 30";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates nested mappings", () => {
      const yaml = "person:\n  name: John\n  age: 30";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates sequences (lists)", () => {
      const yaml = "items:\n  - apple\n  - banana\n  - cherry";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates mixed mappings and sequences", () => {
      const yaml = "users:\n  - name: John\n    age: 30\n  - name: Jane\n    age: 28";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates comments", () => {
      const yaml = "# This is a comment\nname: John\n# Another comment\nage: 30";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates double-quoted strings", () => {
      const yaml = 'message: "Hello, World!"';
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates single-quoted strings", () => {
      const yaml = "message: 'Hello, World!'";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates empty file", () => {
      const yaml = "";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates numeric values", () => {
      const yaml = "count: 42\nprice: 19.99\nnegative: -5";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates boolean values", () => {
      const yaml = "active: true\ninactive: false";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates null values", () => {
      const yaml = "empty: null\nanother: ~";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates inline bracket notation", () => {
      const yaml = "items: [apple, banana, cherry]";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates inline brace notation", () => {
      const yaml = "person: {name: John, age: 30}";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });

  // Invalid YAML tests
  describe("detects invalid YAML", () => {
    test("detects bad indentation", () => {
      const yaml = "parent:\n    child: value1\n  bad_indent: value2";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("detects unclosed double quotes", () => {
      const yaml = 'name: "unclosed';
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("detects unclosed single quotes", () => {
      const yaml = "name: 'unclosed";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("detects unclosed bracket", () => {
      const yaml = "items: [apple, banana, cherry";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("detects unclosed brace", () => {
      const yaml = "person: {name: John, age: 30";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });
  });

  // Error location tracking
  describe("tracks error locations", () => {
    test("reports correct line number for error", () => {
      const yaml = "valid: true\ninvalid format here\nanother: line";
      const result = validateYAML(yaml, "test.yaml");
      if (!result.valid && result.errors.length > 0) {
        // Error should be on line 2
        expect(result.errors[0].line).toBeGreaterThan(0);
      }
    });

    test("reports error with file name", () => {
      const yaml = 'unclosed: "string';
      const result = validateYAML(yaml, "config.yaml");
      expect(result.file).toBe("config.yaml");
      if (!result.valid) {
        expect(result.errors[0].file).toBeDefined();
      }
    });

    test("includes error context", () => {
      const yaml = "valid: line\n'unclosed quote\nanother: line";
      const result = validateYAML(yaml, "test.yaml");
      if (!result.valid && result.errors.length > 0) {
        const error = result.errors[0];
        expect(error.message).toBeDefined();
        expect(error.line).toBeGreaterThan(0);
        expect(error.column).toBeGreaterThanOrEqual(0);
      }
    });
  });

  // Edge cases
  describe("handles edge cases", () => {
    test("validates multiple consecutive comments", () => {
      const yaml = "# Comment 1\n# Comment 2\n# Comment 3\nvalue: 123";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("validates empty mappings", () => {
      const yaml = "empty:";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("validates lines with only whitespace", () => {
      const yaml = "name: John\n   \nage: 30";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("validates quoted strings with colons", () => {
      const yaml = 'time: "12:30:45"';
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("validates escaped characters in quotes", () => {
      const yaml = 'message: "Hello\\nWorld"';
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("validates single-line arrays", () => {
      const yaml = "tags: [python, javascript, rust]";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });

    test("validates single-line objects", () => {
      const yaml = "config: {debug: true, timeout: 30}";
      const result = validateYAML(yaml, "test.yaml");
      expect(result.valid).toBe(true);
    });
  });

  // ValidationResult structure
  describe("returns correct ValidationResult structure", () => {
    test("valid result has correct fields", () => {
      const yaml = "key: value";
      const result = validateYAML(yaml, "test.yaml");

      expect(result).toHaveProperty("valid");
      expect(result).toHaveProperty("file");
      expect(result).toHaveProperty("errors");
      expect(Array.isArray(result.errors)).toBe(true);
    });

    test("invalid result includes error details", () => {
      const yaml = 'unclosed: "string';
      const result = validateYAML(yaml, "test.yaml");

      expect(result.valid).toBe(false);
      if (result.errors.length > 0) {
        const error = result.errors[0];
        expect(error).toHaveProperty("file");
        expect(error).toHaveProperty("line");
        expect(error).toHaveProperty("column");
        expect(error).toHaveProperty("message");
      }
    });

    test("file name is preserved in result", () => {
      const yaml = "key: value";
      const result = validateYAML(yaml, "myconfig.yaml");

      expect(result.file).toBe("myconfig.yaml");
    });
  });

  // Realistic YAML examples
  describe("validates realistic YAML files", () => {
    test("validates Kubernetes-like manifest", () => {
      const yaml = `apiVersion: v1
kind: Service
metadata:
  name: my-service
  labels:
    app: MyApp
spec:
  selector:
    app: MyApp
  ports:
    - protocol: TCP
      port: 80
      targetPort: 9376`;

      const result = validateYAML(yaml, "service.yaml");
