   357→        while (
   358→          indentStack.length > 1 &&
   359→          indentStack[indentStack.length - 1] > indent
   360→        ) {
   361→          indentStack.pop();
   362→        }
   363→
   364→        if (indent !== indentStack[indentStack.length - 1]) {
   365→          errors.push({
   366→            file: "unknown",
   367→            line: token.line,
   368→            column: token.column,
   369→            message:
   370→              "Invalid indentation - does not align with previous indentation levels",
   371→            context: lines[token.line - 1],
