/**
 * YAML syntax validator using Bun.YAML.parse()
 * No external dependencies - uses only built-in Bun/Node.js APIs.
 *
 * This module wraps Bun's built-in YAML parsing capability to provide
 * structured validation results with error location information.
 */

export interface ValidationError {
  file: string;
  line: number;
  column: number;
  message: string;
  context?: string;
}

export interface ValidationResult {
  valid: boolean;
  file: string;
  errors: ValidationError[];
}

/**
 * Extracts surrounding context lines for error reporting.
 */
function extractContext(
  content: string,
  errorLine: number | undefined
): string | undefined {
  if (!errorLine) return undefined;

  const lines = content.split("\n");
  const lineIndex = errorLine - 1;

  if (lineIndex < 0 || lineIndex >= lines.length) {
    return undefined;
  }

  return lines[lineIndex];
}

/**
 * Validates YAML content from a string using Bun.YAML.parse()
 * Returns a ValidationResult with error details if invalid.
 */
export function validateYAML(
  content: string,
  filename: string
): ValidationResult {
  try {
    Bun.YAML.parse(content);
    return {
      valid: true,
      file: filename,
      errors: [],
    };
  } catch (error) {
    if (error instanceof SyntaxError) {
      const yamlError = error as any;
      return {
        valid: false,
        file: filename,
        errors: [
          {
            file: filename,
            line: yamlError.line ?? 1,
            column: yamlError.column ?? 0,
            message: error.message,
            context: extractContext(content, yamlError.line),
          },
        ],
      };
    }
    throw error;
  }
}

/**
 * Parses YAML content using Bun.YAML.parse()
 * This is an alias for validateYAML that emphasizes the parsing aspect.
 * Returns a ValidationResult indicating success or failure with error details.
 */
export function parseYAML(content: string): ValidationResult {
  try {
    Bun.YAML.parse(content);
    return {
      valid: true,
      file: "input",
      errors: [],
    };
  } catch (error) {
    if (error instanceof SyntaxError) {
      const yamlError = error as any;
      return {
        valid: false,
        file: "input",
        errors: [
          {
            file: "input",
            line: yamlError.line ?? 1,
            column: yamlError.column ?? 0,
            message: error.message,
            context: extractContext(content, yamlError.line),
          },
        ],
      };
    }
    throw error;
  }
}

/**
 * Validates a single YAML file from the file system.
 */
export function validateYAMLFile(filePath: string): ValidationResult {
  try {
    const content = Bun.file(filePath).text();
    return validateYAML(content, filePath);
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Unknown file error";
    return {
      valid: false,
      file: filePath,
      errors: [
        {
          file: filePath,
          line: 0,
          column: 0,
          message: `File error: ${message}`,
        },
      ],
    };
  }
}

/**
 * Validates multiple YAML files from the file system.
 */
export function validateYAMLFiles(filePaths: string[]): ValidationResult[] {
  return filePaths.map((filePath) => validateYAMLFile(filePath));
}

