    12→
    13→function showHelp(): void {
    14→  console.log(`YAML Validator - Syntax validation for YAML files
    15→
    16→Usage:
    17→  bun run validate-yaml <file> [file2] [file3] ...
    18→  bun run validate-yaml --help
    19→
    20→Options:
    21→  --help     Show this help message
    22→
    23→Examples:
    24→  bun run validate-yaml config.yaml
    25→  bun run validate-yaml *.yaml
    26→  bun run validate-yaml config1.yaml config2.yaml config3.yaml
    27→
    28→Exit Codes:
    29→  0    All files are valid
    30→  1    One or more files have syntax errors
    31→  2    Command-line error (invalid usage)`);
    32→}
    33→
    34→function formatErrorOutput(results: ValidationResult[]): void {
    35→  const invalidResults = results.filter((r) => !r.valid);
    36→  invalidResults.forEach((result) => {
    37→    result.errors.forEach((error) => {
    38→      if (error.line === 0 && error.column === 0) {
    39→        console.error(`ERROR: ${error.file}`);
    40→        console.error(`  ${error.message}`);
    41→      } else {
    42→        console.error(
    43→          `ERROR: ${error.file} (line ${error.line}, column ${error.column})`
    44→        );
    45→        console.error(`  ${error.message}`);
    46→        if (error.context) {
    47→          console.error(`  > ${error.context}`);
    48→        }
    49→      }
    50→    });
    51→  });
    52→}
    53→
    54→function formatSuccessOutput(results: ValidationResult[]): void {
    55→  const validCount = results.filter((r) => r.valid).length;
    56→  console.log(
    57→    `✓ Validation successful: ${validCount}/${results.length} file(s) valid`
    58→  );
    59→}
    60→
    61→function runValidator(args: string[]): void {
    62→  if (args.length === 0 || args.includes("--help") || args.includes("-h")) {
    63→    showHelp();
    64→    if (args.length === 0) {
    65→      process.exitCode = 2;
    66→    }
    67→    return;
    68→  }
    69→
    70→  const filePaths = args.filter((arg) => !arg.startsWith("--"));
    71→  if (filePaths.length === 0) {
    72→    console.error("Error: No files specified");
    73→    showHelp();
    74→    process.exitCode = 2;
    75→    return;
    76→  }
    77→
    78→  const results = validateYAMLFiles(filePaths);
    79→  const allValid = results.every((r) => r.valid);
    80→
    81→  if (allValid) {
    82→    formatSuccessOutput(results);
    83→    process.exitCode = 0;
    84→  } else {
    85→    formatErrorOutput(results);
    86→    process.exitCode = 1;
    87→  }
    88→}
    89→
    90→function main(): void {
    91→  const args = process.argv.slice(2);
    92→
    93→  if (process.env.VALIDATE_YAML === "true" || args[0] === "--validate-yaml") {
    94→    const validatorArgs = process.env.VALIDATE_YAML === "true" ? args : args.slice(1);
    95→    runValidator(validatorArgs);
    96→  } else {
    97→    const name = args[0] ?? "World";
    98→    console.log(greet(name));
    99→  }
   100→}
