    32→  context?: string;
    33→}
    34→
    35→export interface ValidationResult {
    36→  valid: boolean;
    37→  file: string;
    38→  errors: ValidationError[];
    39→}
    40→
    41→/**
    42→ * Validates YAML content from a string.
    43→ * Returns a ValidationResult with error details if invalid.
    44→ */
    45→export function validateYAML(
    46→  content: string,
    47→  filename: string
    48→): ValidationResult {
    49→  const errors: ValidationError[] = [];
    50→  const lines = content.split("\n");
    51→
    52→  try {
    53→    const tokens = tokenize(content);
    54→    const parseResult = parseTokens(tokens, lines);
    55→
    56→    if (!parseResult.valid) {
    57→      errors.push(...parseResult.errors);
    58→    }
    59→  } catch (error) {
    60→    const message =
    61→      error instanceof Error ? error.message : "Unknown parsing error";
    62→    errors.push({
    63→      file: filename,
    64→      line: 1,
    65→      column: 0,
    66→      message: `Parse error: ${message}`,
    67→    });
    68→  }
    69→
    70→  return {
    71→    valid: errors.length === 0,
    72→    file: filename,
    73→    errors,
    74→  };
    75→}
    76→
    77→/**
    78→ * Validates multiple YAML files.
    79→ * Uses only fs module which is available in Bun runtime.
    80→ */
    81→export function validateYAMLFiles(filePaths: string[]): ValidationResult[] {
    82→  const results: ValidationResult[] = [];
    83→
    84→  for (const filePath of filePaths) {
    85→    try {
    86→      // Use Bun/Node.js built-in fs module
    87→      const fs = require("fs");
    88→      const content = fs.readFileSync(filePath, "utf-8");
    89→      results.push(validateYAML(content, filePath));
    90→    } catch (error) {
    91→      const message =
    92→        error instanceof Error ? error.message : "Unknown file error";
    93→      results.push({
    94→        valid: false,
    95→        file: filePath,
    96→        errors: [
    97→          {
    98→            file: filePath,
    99→            line: 0,
   100→            column: 0,
   101→            message: `File error: ${message}`,
   102→          },
   103→        ],
   104→      });
   105→    }
   106→  }
   107→
   108→  return results;
   109→}
   110→
   111→/**
   112→ * Tokenizes YAML content into a stream of tokens.
   113→ * Extracts tokens with type, value, and position information.
   114→ */
   115→function tokenize(content: string): Token[] {
   116→  const tokens: Token[] = [];
   117→  let line = 1;
   118→  let column = 0;
   119→  let i = 0;
   120→
   121→  while (i < content.length) {
   122→    const char = content[i];
   123→    const nextChar = content[i + 1];
   124→    const startColumn = column;
   125→
   126→    // Newline
   127→    if (char === "\n") {
   128→      tokens.push({
   129→        type: "newline",
   130→        value: "\n",
   131→        line,
   132→        column: startColumn,
   133→      });
   134→      line++;
   135→      column = 0;
   136→      i++;
   137→      continue;
   138→    }
   139→
   140→    // Comments (must be at line start or after space)
   141→    if (char === "#" && (column === 0 || /\s/.test(content[i - 1]))) {
   142→      const start = i;
   143→      while (i < content.length && content[i] !== "\n") {
   144→        i++;
   145→      }
   146→      tokens.push({
   147→        type: "comment",
   148→        value: content.substring(start, i),
   149→        line,
   150→        column: startColumn,
   151→      });
   152→      column += i - start;
   153→      continue;
   154→    }
   155→
   156→    // Indentation (spaces at line start)
   157→    if (column === 0 && char === " ") {
   158→      const start = i;
   159→      while (i < content.length && content[i] === " ") {
   160→        i++;
   161→      }
   162→      const indentSize = i - start;
   163→      tokens.push({
   164→        type: "indent",
   165→        value: " ".repeat(indentSize),
   166→        line,
   167→        column: 0,
   168→      });
   169→      column = indentSize;
   170→      continue;
   171→    }
   172→
   173→    // Quoted strings (single or double)
   174→    if (char === '"' || char === "'") {
   175→      const quote = char;
   176→      const start = i;
   177→      i++;
   178→      column++;
   179→
   180→      while (i < content.length && content[i] !== quote) {
   181→        if (content[i] === "\\" && content[i + 1]) {
   182→          i += 2;
   183→          column += 2;
   184→        } else {
   185→          i++;
   186→          column++;
   187→        }
   188→      }
   189→
   190→      if (i >= content.length) {
   191→        // Unclosed quote
   192→        tokens.push({
   193→          type: "quote",
   194→          value: content.substring(start, i),
   195→          line,
   196→          column: startColumn,
   197→        });
   198→        break;
   199→      }
   200→
   201→      i++; // closing quote
   202→      column++;
   203→      tokens.push({
   204→        type: "quote",
   205→        value: content.substring(start, i),
   206→        line,
   207→        column: startColumn,
   208→      });
   209→      continue;
   210→    }
   211→
   212→    // Structural characters
   213→    if (char === ":") {
   214→      tokens.push({
   215→        type: "colon",
   216→        value: ":",
   217→        line,
   218→        column: startColumn,
   219→      });
   220→      i++;
   221→      column++;
   222→      continue;
   223→    }
   224→
   225→    if (char === "-" && (nextChar === undefined || /[\s:]/.test(nextChar))) {
   226→      tokens.push({
   227→        type: "dash",
   228→        value: "-",
   229→        line,
   230→        column: startColumn,
   231→      });
   232→      i++;
   233→      column++;
   234→      continue;
   235→    }
   236→
   237→    if (char === "{") {
   238→      tokens.push({
   239→        type: "brace",
   240→        value: "{",
   241→        line,
   242→        column: startColumn,
   243→      });
   244→      i++;
   245→      column++;
   246→      continue;
   247→    }
   248→
   249→    if (char === "}") {
   250→      tokens.push({
   251→        type: "brace",
   252→        value: "}",
   253→        line,
   254→        column: startColumn,
   255→      });
   256→      i++;
   257→      column++;
   258→      continue;
   259→    }
   260→
   261→    if (char === "[") {
   262→      tokens.push({
   263→        type: "bracket",
   264→        value: "[",
   265→        line,
   266→        column: startColumn,
   267→      });
   268→      i++;
   269→      column++;
   270→      continue;
   271→    }
   272→
   273→    if (char === "]") {
   274→      tokens.push({
   275→        type: "bracket",
   276→        value: "]",
   277→        line,
   278→        column: startColumn,
   279→      });
   280→      i++;
   281→      column++;
   282→      continue;
   283→    }
   284→
   285→    if (char === ",") {
   286→      tokens.push({
   287→        type: "comma",
   288→        value: ",",
   289→        line,
   290→        column: startColumn,
   291→      });
   292→      i++;
   293→      column++;
   294→      continue;
   295→    }
   296→
   297→    // Scalars (everything else)
   298→    const start = i;
   299→    while (
   300→      i < content.length &&
   301→      !/[\n:,\[\]{}"']/.test(content[i]) &&
   302→      !(
   303→        content[i] === "#" &&
   304→        (column === 0 || /\s/.test(content[i - 1]))
   305→      )
   306→    ) {
   307→      i++;
   308→    }
   309→
   310→    if (i > start) {
   311→      const value = content.substring(start, i).trimEnd();
   312→      if (value) {
   313→        tokens.push({
   314→          type: "scalar",
   315→          value,
   316→          line,
   317→          column: startColumn,
   318→        });
   319→      }
   320→      column += i - start;
   321→    }
   322→
   323→    // Skip remaining whitespace (except newlines)
   324→    while (i < content.length && /[ \t]/.test(content[i])) {
   325→      i++;
   326→      column++;
   327→    }
   328→  }
   329→
   330→  return tokens;
   331→}
   332→
   333→/**
   334→ * Parses tokens into an abstract structure and validates YAML syntax.
   335→ */
   336→function parseTokens(
   337→  tokens: Token[],
   338→  lines: string[]
   339→): { valid: boolean; errors: ValidationError[] } {
   340→  const errors: ValidationError[] = [];
   341→  let i = 0;
   342→
   343→  // Track indentation stack for structure validation
   344→  const indentStack: number[] = [0];
   345→  let expectingValue = false;
   346→
   347→  while (i < tokens.length) {
   348→    const token = tokens[i];
   349→
   350→    // Process indentation changes
   351→    if (token.type === "indent") {
   352→      const indent = token.value.length;
   353→
   354→      if (indent > indentStack[indentStack.length - 1]) {
   355→        indentStack.push(indent);
   356→      } else if (indent < indentStack[indentStack.length - 1]) {
   357→        while (
   358→          indentStack.length > 1 &&
   359→          indentStack[indentStack.length - 1] > indent
   360→        ) {
   361→          indentStack.pop();
   362→        }
   363→
   364→        if (indent !== indentStack[indentStack.length - 1]) {
   365→          errors.push({
   366→            file: "unknown",
   367→            line: token.line,
   368→            column: token.column,
   369→            message:
   370→              "Invalid indentation - does not align with previous indentation levels",
   371→            context: lines[token.line - 1],
   372→          });
   373→        }
   374→      }
   375→    }
   376→
   377→    // Validate structure patterns
   378→    if (token.type === "colon") {
   379→      // Colon must have a value (scalar/quote) before it
   380→      if (i === 0 || tokens[i - 1].type === "colon") {
   381→        errors.push({
   382→          file: "unknown",
   383→          line: token.line,
   384→          column: token.column,
   385→          message: "Unexpected colon - expected key name before colon",
   386→          context: lines[token.line - 1],
   387→        });
   388→      }
   389→
   390→      // After colon, must have value or newline
   391→      if (
   392→        i + 1 < tokens.length &&
   393→        tokens[i + 1].type !== "newline" &&
   394→        tokens[i + 1].type !== "comment" &&
   395→        tokens[i + 1].type !== "scalar" &&
   396→        tokens[i + 1].type !== "quote" &&
   397→        tokens[i + 1].type !== "dash" &&
   398→        tokens[i + 1].type !== "bracket" &&
   399→        tokens[i + 1].type !== "brace"
   400→      ) {
   401→        // Value is optional in YAML (null value allowed)
   402→      }
   403→    }
   404→
   405→    // Detect unclosed quotes
   406→    if (token.type === "quote" && token.value[0] === token.value[0]) {
   407→      if (!token.value.endsWith(token.value[0])) {
   408→        errors.push({
   409→          file: "unknown",
   410→          line: token.line,
   411→          column: token.column,
   412→          message: `Unclosed ${token.value[0] === '"' ? "double" : "single"} quote`,
   413→          context: lines[token.line - 1],
   414→        });
   415→      }
   416→    }
   417→
   418→    // Check for dash without proper spacing (must be followed by space or bracket)
   419→    if (token.type === "dash") {
   420→      if (
   421→        i + 1 < tokens.length &&
   422→        tokens[i + 1].type !== "newline" &&
   423→        tokens[i + 1].type !== "comment"
   424→      ) {
   425→        const nextToken = tokens[i + 1];
   426→        if (nextToken.column <= token.column + 1) {
   427→          // Not properly spaced
   428→        }
   429→      }
   430→    }
   431→
   432→    // Validate bracket/brace matching (simple check)
   433→    if (token.type === "bracket" && token.value === "[") {
   434→      let braceCount = 1;
   435→      let j = i + 1;
   436→      while (j < tokens.length && braceCount > 0) {
   437→        if (tokens[j].type === "bracket") {
   438→          braceCount += tokens[j].value === "[" ? 1 : -1;
   439→        }
   440→        j++;
   441→      }
   442→      if (braceCount !== 0) {
   443→        errors.push({
   444→          file: "unknown",
   445→          line: token.line,
   446→          column: token.column,
   447→          message: "Unclosed bracket",
   448→          context: lines[token.line - 1],
   449→        });
   450→      }
   451→    }
   452→
   453→    if (token.type === "brace" && token.value === "{") {
   454→      let braceCount = 1;
   455→      let j = i + 1;
   456→      while (j < tokens.length && braceCount > 0) {
   457→        if (tokens[j].type === "brace") {
   458→          braceCount += tokens[j].value === "{" ? 1 : -1;
   459→        }
   460→        j++;
   461→      }
   462→      if (braceCount !== 0) {
   463→        errors.push({
   464→          file: "unknown",
   465→          line: token.line,
   466→          column: token.column,
   467→          message: "Unclosed brace",
   468→          context: lines[token.line - 1],
   469→        });
   470→      }
   471→    }
   472→
   473→    i++;
   474→  }
   475→
   476→  return {
   477→    valid: errors.length === 0,
   478→    errors,
   479→  };
   480→}
