     2→ * YAML syntax validator using Bun.YAML.parse()
     3→ * No external dependencies - uses only built-in Bun/Node.js APIs.
     4→ *
     5→ * This module wraps Bun's built-in YAML parsing capability to provide
     6→ * structured validation results with error location information.
     7→ */
     8→
     9→export interface ValidationError {
    10→  file: string;
    11→  line: number;
    12→  column: number;
    13→  message: string;
    14→  context?: string;
    15→}
    16→
    17→export interface ValidationResult {
    18→  valid: boolean;
    19→  file: string;
    20→  errors: ValidationError[];
    21→}
    22→
    23→/**
    24→ * Extracts surrounding context lines for error reporting.
    25→ */
    26→function extractContext(
    27→  content: string,
    28→  errorLine: number | undefined
    29→): string | undefined {
    30→  if (!errorLine) return undefined;
    31→
    32→  const lines = content.split("\n");
    33→  const lineIndex = errorLine - 1;
    34→
    35→  if (lineIndex < 0 || lineIndex >= lines.length) {
    36→    return undefined;
    37→  }
    38→
    39→  return lines[lineIndex];
    40→}
    41→
    42→/**
    43→ * Validates YAML content from a string using Bun.YAML.parse()
    44→ * Returns a ValidationResult with error details if invalid.
    45→ */
    46→export function validateYAML(
    47→  content: string,
    48→  filename: string
    49→): ValidationResult {
    50→  try {
    51→    Bun.YAML.parse(content);
    52→    return {
    53→      valid: true,
    54→      file: filename,
    55→      errors: [],
    56→    };
    57→  } catch (error) {
    58→    if (error instanceof SyntaxError) {
    59→      const yamlError = error as any;
    60→      return {
    61→        valid: false,
    62→        file: filename,
    63→        errors: [
    64→          {
    65→            file: filename,
    66→            line: yamlError.line ?? 1,
    67→            column: yamlError.column ?? 0,
    68→            message: error.message,
    69→            context: extractContext(content, yamlError.line),
    70→          },
    71→        ],
    72→      };
    73→    }
    74→    throw error;
    75→  }
    76→}
    77→
    78→/**
    79→ * Parses YAML content using Bun.YAML.parse()
    80→ * This is an alias for validateYAML that emphasizes the parsing aspect.
    81→ * Returns a ValidationResult indicating success or failure with error details.
    82→ */
    83→export function parseYAML(content: string): ValidationResult {
    84→  try {
    85→    Bun.YAML.parse(content);
    86→    return {
    87→      valid: true,
    88→      file: "input",
    89→      errors: [],
    90→    };
    91→  } catch (error) {
    92→    if (error instanceof SyntaxError) {
    93→      const yamlError = error as any;
    94→      return {
    95→        valid: false,
    96→        file: "input",
    97→        errors: [
    98→          {
    99→            file: "input",
   100→            line: yamlError.line ?? 1,
   101→            column: yamlError.column ?? 0,
   102→            message: error.message,
   103→            context: extractContext(content, yamlError.line),
   104→          },
   105→        ],
   106→      };
   107→    }
   108→    throw error;
   109→  }
   110→}
   111→
   112→/**
   113→ * Validates a single YAML file from the file system.
   114→ */
   115→export function validateYAMLFile(filePath: string): ValidationResult {
   116→  try {
   117→    const content = Bun.file(filePath).text();
   118→    return validateYAML(content, filePath);
   119→  } catch (error) {
   120→    const message =
   121→      error instanceof Error ? error.message : "Unknown file error";
   122→    return {
   123→      valid: false,
   124→      file: filePath,
   125→      errors: [
   126→        {
   127→          file: filePath,
   128→          line: 0,
   129→          column: 0,
   130→          message: `File error: ${message}`,
   131→        },
   132→      ],
   133→    };
   134→  }
   135→}
   136→
   137→/**
   138→ * Validates multiple YAML files from the file system.
   139→ */
   140→export function validateYAMLFiles(filePaths: string[]): ValidationResult[] {
   141→  return filePaths.map((filePath) => validateYAMLFile(filePath));
   142→}
