     1→/**
     2→ * YAML syntax validator using Bun.YAML.parse()
     3→ * No external dependencies - uses only built-in Bun/Node.js APIs.
     4→ *
     5→ * This module wraps Bun's built-in YAML parsing capability to provide
     6→ * structured validation results with error location information.
     7→ */
     8→
     9→import { readFileSync } from "fs";
    10→
    11→export interface ValidationError {
    12→  file: string;
    13→  line: number;
    14→  column: number;
    15→  message: string;
    16→  context?: string;
    17→}
    18→
    19→export interface ValidationResult {
    20→  valid: boolean;
    21→  file: string;
    22→  errors: ValidationError[];
    23→}
    24→
    25→/**
    26→ * Extracts surrounding context lines for error reporting.
    27→ */
    28→function extractContext(
    29→  content: string,
    30→  errorLine: number | undefined
    31→): string | undefined {
    32→  if (!errorLine) return undefined;
    33→
    34→  const lines = content.split("\n");
    35→  const lineIndex = errorLine - 1;
    36→
    37→  if (lineIndex < 0 || lineIndex >= lines.length) {
    38→    return undefined;
    39→  }
    40→
    41→  return lines[lineIndex];
    42→}
    43→
    44→/**
    45→ * Validates YAML content from a string using Bun.YAML.parse()
    46→ * Returns a ValidationResult with error details if invalid.
    47→ */
    48→export function validateYAML(
    49→  content: string,
    50→  filename: string
    51→): ValidationResult {
    52→  try {
    53→    Bun.YAML.parse(content);
    54→    return {
    55→      valid: true,
    56→      file: filename,
    57→      errors: [],
    58→    };
    59→  } catch (error) {
    60→    if (error instanceof SyntaxError) {
    61→      const yamlError = error as any;
    62→      return {
    63→        valid: false,
    64→        file: filename,
    65→        errors: [
    66→          {
    67→            file: filename,
    68→            line: yamlError.line ?? 1,
    69→            column: yamlError.column ?? 0,
    70→            message: error.message,
    71→            context: extractContext(content, yamlError.line),
    72→          },
    73→        ],
    74→      };
    75→    }
    76→    throw error;
    77→  }
    78→}
    79→
    80→/**
    81→ * Parses YAML content using Bun.YAML.parse()
    82→ * This is an alias for validateYAML that emphasizes the parsing aspect.
    83→ * Returns a ValidationResult indicating success or failure with error details.
    84→ */
    85→export function parseYAML(content: string): ValidationResult {
    86→  try {
    87→    Bun.YAML.parse(content);
    88→    return {
    89→      valid: true,
    90→      file: "input",
    91→      errors: [],
    92→    };
    93→  } catch (error) {
    94→    if (error instanceof SyntaxError) {
    95→      const yamlError = error as any;
    96→      return {
    97→        valid: false,
    98→        file: "input",
    99→        errors: [
   100→          {
   101→            file: "input",
   102→            line: yamlError.line ?? 1,
   103→            column: yamlError.column ?? 0,
   104→            message: error.message,
   105→            context: extractContext(content, yamlError.line),
   106→          },
   107→        ],
   108→      };
   109→    }
   110→    throw error;
   111→  }
   112→}
   113→
   114→/**
   115→ * Validates a single YAML file from the file system.
   116→ */
   117→export function validateYAMLFile(filePath: string): ValidationResult {
   118→  try {
   119→    const content = readFileSync(filePath, "utf-8");
   120→    return validateYAML(content, filePath);
   121→  } catch (error) {
   122→    const message =
   123→      error instanceof Error ? error.message : "Unknown file error";
   124→    return {
   125→      valid: false,
   126→      file: filePath,
   127→      errors: [
   128→        {
   129→          file: filePath,
   130→          line: 0,
   131→          column: 0,
   132→          message: `File error: ${message}`,
   133→        },
   134→      ],
   135→    };
   136→  }
   137→}
   138→
   139→/**
   140→ * Validates multiple YAML files from the file system.
   141→ */
   142→export function validateYAMLFiles(filePaths: string[]): ValidationResult[] {
   143→  return filePaths.map((filePath) => validateYAMLFile(filePath));
   144→}
