+function showHelp(): void {
+  console.log(`YAML Validator - Syntax validation for YAML files
+
+Usage:
+  bun run validate-yaml <file> [file2] [file3] ...
+  bun run validate-yaml --help
+
+Options:
+  --help     Show this help message
+
+Examples:
+  bun run validate-yaml config.yaml
+  bun run validate-yaml *.yaml
+  bun run validate-yaml config1.yaml config2.yaml config3.yaml
+
+Exit Codes:
+  0    All files are valid
+  1    One or more files have syntax errors
+  2    Command-line error (invalid usage)`);
+}
+
+function formatErrorOutput(results: ValidationResult[]): void {
+  const invalidResults = results.filter((r) => !r.valid);
+  invalidResults.forEach((result) => {
+    result.errors.forEach((error) => {
+      if (error.line === 0 && error.column === 0) {
+        console.error(`ERROR: ${error.file}`);
+        console.error(`  ${error.message}`);
+      } else {
+        console.error(
+          `ERROR: ${error.file} (line ${error.line}, column ${error.column})`
+        );
+        console.error(`  ${error.message}`);
+        if (error.context) {
+          console.error(`  > ${error.context}`);
+        }
+      }
+    });
+  });
+}
+
+function formatSuccessOutput(results: ValidationResult[]): void {
+  const validCount = results.filter((r) => r.valid).length;
+  console.log(
+    `✓ Validation successful: ${validCount}/${results.length} file(s) valid`
+  );
+}
+
+function runValidator(args: string[]): void {
+  if (args.length === 0 || args.includes("--help") || args.includes("-h")) {
+    showHelp();
+    if (args.length === 0) {
+      process.exitCode = 2;
+    }
+    return;
+  }
+
+  const filePaths = args.filter((arg) => !arg.startsWith("--"));
+  if (filePaths.length === 0) {
+    console.error("Error: No files specified");
+    showHelp();
+    process.exitCode = 2;
+    return;
+  }
+
+  const results = validateYAMLFiles(filePaths);
+  const allValid = results.every((r) => r.valid);
+
+  if (allValid) {
+    formatSuccessOutput(results);
+    process.exitCode = 0;
+  } else {
+    formatErrorOutput(results);
+    process.exitCode = 1;
+  }
